    private static (float Min, float Max) FindMinMax512(ref float start, int length)
    {
        int count = Vector512<float>.Count;
        var vMin = Vector512.LoadUnsafe(ref start);
        var vMax = vMin;

        int i = count;
        int limit = length - count;

        // Unroll two iterations to increase ILP
        int limit2 = length - count * 2;
        while (i <= limit2)
        {
            var v0 = Vector512.LoadUnsafe(ref start, (nuint)i);
            var v1 = Vector512.LoadUnsafe(ref start, (nuint)(i + count));
            vMin = Vector512.Min(vMin, Vector512.Min(v0, v1));
            vMax = Vector512.Max(vMax, Vector512.Max(v0, v1));
            i += count * 2;
        }

        while (i <= limit)
        {
            var v = Vector512.LoadUnsafe(ref start, (nuint)i);
            vMin = Vector512.Min(vMin, v);
            vMax = Vector512.Max(vMax, v);
            i += count;
        }

        // Reduce 512 -> scalar
        var lo256 = vMin.GetLower();
        var hi256 = vMin.GetUpper();
        var min256 = Vector256.Min(lo256, hi256);
        var min128 = Vector128.Min(min256.GetLower(), min256.GetUpper());

        lo256 = vMax.GetLower();
        hi256 = vMax.GetUpper();
        var max256 = Vector256.Max(lo256, hi256);
        var max128 = Vector128.Max(max256.GetLower(), max256.GetUpper());

        float min = HorizontalMin(min128);
        float max = HorizontalMax(max128);

        // Handle remaining elements
        for (; i < length; i++)
        {
            float val = Unsafe.Add(ref start, i);
            if (val < min) min = val;
            if (val > max) max = val;
        }

        return (min, max);
    }

